  function pagerHtml(page, pages) {
    const nums = []
    for (let i = 1; i <= pages; i++) {
      if (pages > 9 && i > 2 && i < pages - 1 && Math.abs(i - page) > 1) {
        if (nums.at(-1) !== '…') nums.push('…')
        continue
      }
      nums.push(i)
    }
    return [
      `‹`,
      ...nums.map((n) =>
        n === '…'
          ? `…`
          : `${n}`,
      ),
      `›`,
    ].join('')
  }

  function crumb(parts) {
    return `
