def main():
    seen = {}
    services = []
    for row in RAW:
        code, title, official, sits, ecp, no_id, org, term, cost, fmt = row
        if code in seen:
            continue
        seen[code] = True
        slug = code.replace("/", "-").replace(" ", "")
        services.append({
            "id": slug,
            "code": code,
            "title": title,
            "official": official,
            "situations": sits,
            "ecp": ecp,
            "noId": no_id,
            "org": ORGS[org],
            "result": {"term": term, "cost": cost, "format": fmt},
            "steps": [
                "Проверьте, что данные о вас подтянутся из реестров — вручную заполнять нужно только недостающее.",
                "Заполните форму. Черновик сохраняется сам, можно закрыть вкладку и вернуться.",
                "Отправьте заявление. Статус появится в «Мои услуги» (раздел — в следующем этапе).",
            ],
        })

    payload = {
        "services": services,
        "situations": SITUATIONS,
        "quickActions": QUICK,
        "synonyms": SYNONYMS,
        "totalOfficial": 174,
    }
    out = Path("js/data.js")
    out.parent.mkdir(exist_ok=True)
    out.write_text(
        "window.EPASLUGA_DATA = " + json.dumps(payload, ensure_ascii=False, indent=2) + ";\n",
        encoding="utf-8",
    )
    print(f"wrote {len(services)} services")


if __name__ == "__main__":
    main()



# Е-Паслуга — прототип (срез 1)

Статический прототип трёх экранов: главная, каталог, карточка услуги.

Цвета и левое меню как на текущем портале. Кликабельны только главная («Мой профиль»), «Все услуги» и карточки услуг.

## Запуск

В папке проекта:

```bash
python3 -m http.server 4173
```

Откройте http://127.0.0.1:4173/

## Что уже есть

- Жизненные ситуации и быстрые действия на главной
- Человеческие названия + официальная формулировка и код
- Бейдж «Без ID-карты» у справочных услуг, «ЭЦП — нужна подпись» с пояснением
- Поиск с синонимами (доходы, паспорт, авто, пенсия…)
- Карточка: блок «Что вы получите», организация и УНП
- Универсальная форма: живая валидация, автосохранение черновика, демо-отправка

Описания сроков и стоимости — заглушки до ваших регламентов.



@echo off
chcp 65001 >nul
cd /d "%~dp0"

where python >nul 2>&1
if %errorlevel%==0 (
  set PY=python
) else (
  where py >nul 2>&1
  if %errorlevel%==0 (
    set PY=py
  ) else (
    echo Python не найден. Установите Python 3 и отметьте "Add python.exe to PATH".
    pause
    exit /b 1
  )
)

echo Прототип Е-Паслуга: http://127.0.0.1:4173/
echo Окно не закрывайте, пока смотрите сайт. Чтобы остановить — Ctrl+C.
start "" "http://127.0.0.1:4173/"
%PY% -m http.server 4173 --bind 127.0.0.1
pause



#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")"

if ! command -v python3 >/dev/null 2>&1; then
  echo "Python 3 не найден. Установите пакет python3 и запустите снова."
  exit 1
fi

echo "Прототип Е-Паслуга: http://127.0.0.1:4173/"
echo "Это окно не закрывайте, пока смотрите сайт. Остановка — Ctrl+C."

if command -v xdg-open >/dev/null 2>&1; then
  (sleep 0.4 && xdg-open "http://127.0.0.1:4173/") >/dev/null 2>&1 &
fi

exec python3 -m http.server 4173 --bind 127.0.0.1






































