export function AiAssistant() {
  const [isOpen, setIsOpen] = useState(false)
  const [messages, setMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([
    { role: 'ai', text: 'Здравствуйте! Я — цифровой помощник. Чем я могу вам помочь?' }
  ])
  const [input, setInput] = useState('')

  const quickQuestions = [
    'Как получить справку о доходах?',
    'Как войти через ID-карту?',
    'Сколько стоит проверка недвижимости?'
  ]

  const handleSend = (text: string) => {
    if (!text.trim()) return
    setMessages(prev => [...prev, { role: 'user', text }])
    setInput('')

    // Имитация ответа ИИ
    setTimeout(() => {
      setMessages(prev => [...prev, { 
        role: 'ai', 
        text: 'Я нашел информацию по вашему вопросу. Вы можете оформить эту услугу в разделе «Каталог услуг». Если нужна помощь с ID-картой, перейдите по ссылке в разделе «О портале».' 
      }])
    }, 1000)
  }

  return (
    <>
      {/* Кнопка вызова чата */}
       setIsOpen(true)}
        className={clsx(
          'fixed bottom-6 right-6 w-14 h-14 bg-navy text-white rounded-full shadow-lg flex items-center justify-center hover:bg-navy-deep transition-transform hover:scale-105 z-40',
          isOpen && 'hidden'
        )}
        aria-label="Открыть ИИ-помощника"
      >





      {/* Окно чата */}
      {isOpen && (


          {/* Шапка чата */}






              ИИ-Помощник

             setIsOpen(false)} className="text-white/80 hover:text-white">






          {/* История сообщений */}


            {messages.map((msg, i) => (




                  {msg.text}


            ))}


          {/* Чипсы с быстрыми вопросами (п. #5 аудита) */}
          {messages.length === 1 && (


              {quickQuestions.map(q => (
                 handleSend(q)}
                  className="text-xs bg-soft text-navy px-3 py-1.5 rounded-full hover:bg-navy hover:text-white transition-colors border border-navy/20"
                >
                  {q}

              ))}

          )}

          {/* Поле ввода */}


             setInput(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleSend(input)}
              placeholder="Напишите вопрос..."
              className="flex-1 bg-bg rounded-full px-4 py-2 text-sm outline-none focus:ring-2 focus:ring-navy/20"
            />
             handleSend(input)} className="text-navy p-2 hover:bg-soft rounded-full">






      )}
    </>
  )
}



export interface Service {
  id: string
  title: string            // Человеческое название (напр. "Справка о доходах")
  officialTitle: string    // Официальное название с кодом
  description: string      // Краткое описание
  category: string         // Категория (напр. "Налоги", "Недвижимость")
  situation?: string       // Жизненная ситуация (напр. "Покупка авто")
  authLevel: 'none' | 'id' | 'ecp' // Что нужно для входа
  timeToComplete: string   // Срок оказания (напр. "3 дня")
  cost: string             // Стоимость (напр. "Бесплатно")
  format: string           // Формат результата (напр. "PDF-файл")
  orgName: string          // Название ведомства
  orgUnp: string           // УНП ведомства
}



{
  "semi": false,
  "singleQuote": true,
  "trailingComma": "all",
  "printWidth": 100,
  "tabWidth": 2
}



{
  "compilerOptions": {
    "tsBuildInfoFile": "./node_modules/.tmp/tsconfig.app.tsbuildinfo",
    "target": "es2023",
    "lib": ["ES2023", "DOM"],
    "module": "esnext",
    "types": ["vite/client"],
    "allowArbitraryExtensions": true,
    "skipLibCheck": true,

    /* Bundler mode */
    "moduleResolution": "bundler",
    "allowImportingTsExtensions": true,
    "verbatimModuleSyntax": true,
    "moduleDetection": "force",
    "noEmit": true,
    "jsx": "react-jsx",

    /* Linting */
    "noUnusedLocals": true,
    "noUnusedParameters": true,
    "erasableSyntaxOnly": true,
    "noFallthroughCasesInSwitch": true
  },
  "include": ["src"]
}



{
  "compilerOptions": {
    "tsBuildInfoFile": "./node_modules/.tmp/tsconfig.node.tsbuildinfo",
    "target": "es2023",
    "lib": ["ES2023"],
    "types": ["node"],
    "skipLibCheck": true,

    /* Bundler mode */
    "module": "nodenext",
    "allowImportingTsExtensions": true,
    "verbatimModuleSyntax": true,
    "moduleDetection": "force",
    "noEmit": true,

    /* Linting */
    "noUnusedLocals": true,
    "noUnusedParameters": true,
    "erasableSyntaxOnly": true,
    "noFallthroughCasesInSwitch": true
  },
  "include": ["vite.config.ts"]
}



:root {
  --navy: #2f3bbd;
  --navy-deep: #1e2a8a;
  --ink: #1a1d2b;
  --muted: #5a6078;
  --line: #e2e5f0;
  --bg: #f3f4f8;
  --card: #ffffff;
  --soft: #eef0f8;
  --danger: #b42318;
  --ok: #17663d;
  --shadow: 0 10px 30px rgba(30, 42, 120, 0.07);
  --radius: 14px;
  --sidebar-w: 248px;
  --rail: 96px;
  --font: 'Segoe UI', 'PT Sans', 'Roboto', Arial, sans-serif;
}

* {
  box-sizing: border-box;
}
html,
body {
  margin: 0;
  min-height: 100%;
}
body {
  font-family: var(--font);
  color: var(--ink);
  background: var(--bg);
  font-size: 15.5px;
  line-height: 1.5;
}

.app {
  display: block;
  min-height: 100vh;
  padding-left: var(--rail);
}

.sidebar {
  background: var(--navy);
  color: #fff;
  position: fixed;
  left: 0;
  top: 0;
  bottom: 0;
  width: var(--rail);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  z-index: 40;
  transition: width 0.2s ease;
}
.sidebar:hover,
.sidebar:focus-within {
  width: var(--sidebar-w);
  box-shadow: 10px 0 32px rgba(20, 24, 80, 0.22);
  overflow: auto;
}
.brand {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 18px 8px 14px;
  text-decoration: none;
  color: #fff;
  font-weight: 700;
  font-size: 20px;
  min-height: 72px;
  white-space: nowrap;
}
.sidebar:hover .brand,
.sidebar:focus-within .brand {
  justify-content: flex-start;
  padding: 18px 16px 14px;
}
.brand-mark {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  flex: 0 0 32px;
  background: conic-gradient(from 200deg, #7dd3fc, #86efac, #93c5fd, #7dd3fc);
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.35);
}
.brand-short {
  font-size: 16px;
  letter-spacing: 0.04em;
  font-weight: 800;
}
.brand-text {
  opacity: 0;
  width: 0;
  overflow: hidden;
  pointer-events: none;
}
.brand-sub,
.nav-label,
.nav-item > span:not(.nav-caret),
.nav-sub span {
  opacity: 0;
  white-space: nowrap;
  overflow: hidden;
  max-width: 0;
  margin: 0;
  padding: 0;
  pointer-events: none;
  flex: 0 0 0;
}
.sidebar:hover .brand-short,
.sidebar:focus-within .brand-short {
  display: none;
}
.sidebar:hover .brand-text,
.sidebar:focus-within .brand-text {
  opacity: 1;
  width: auto;
  pointer-events: auto;
}
.sidebar:hover .brand-sub,
.sidebar:focus-within .brand-sub,
.sidebar:hover .nav-label,
.sidebar:focus-within .nav-label {
  opacity: 1;
  max-width: none;
  pointer-events: auto;
  flex: 0 0 auto;
}
.sidebar:hover .nav-item > span:not(.nav-caret),
.sidebar:focus-within .nav-item > span:not(.nav-caret),
.sidebar:hover .nav-sub span,
.sidebar:focus-within .nav-sub span {
  opacity: 1;
  max-width: 280px;
  pointer-events: auto;
  flex: 1 1 auto;
  overflow: visible;
  line-height: 1.25;
}
.sidebar:hover .nav-nl,
.sidebar:focus-within .nav-nl {
  display: block;
}
.brand-sub {
  padding: 0;
  font-size: 12px;
  color: rgba(255, 255, 255, 0.7);
}
.sidebar:hover .brand-sub,
.sidebar:focus-within .brand-sub {
  padding: 0 18px 16px;
}
.nav-item,
.nav-sub {
  min-height: 48px;
  justify-content: center;
}
.sidebar:hover .nav-item,
.sidebar:focus-within .nav-item,
.sidebar:hover .nav-sub,
.sidebar:focus-within .nav-sub {
  justify-content: flex-start;
}

.nav-label {
  height: 10px;
  margin: 4px 0;
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.55);
}
.sidebar:hover .nav-label,
.sidebar:focus-within .nav-label {
  height: auto;
  margin: 10px 18px 4px;
}
.nav {
  display: flex;
  flex-direction: column;
  padding-bottom: 28px;
}
.nav-item,
.nav-sub {
  display: flex;
  align-items: center;
  gap: 0;
  color: #fff;
  text-decoration: none;
  padding: 10px 0;
  font-size: 13.5px;
  border: 0;
  background: transparent;
  width: 100%;
  text-align: left;
  cursor: pointer;
  font-family: inherit;
  border-radius: 0;
}
.sidebar:hover .nav-item,
.sidebar:focus-within .nav-item {
  padding: 8px 16px;
  gap: 10px;
}
.sidebar:hover .nav-sub,
.sidebar:focus-within .nav-sub {
  padding: 8px 16px 8px 44px;
  gap: 10px;
}
.nav-item:hover,
.nav-sub:hover {
  background: rgba(255, 255, 255, 0.08);
}
.nav-item.is-active,
.nav-sub.is-active {
  background: rgba(255, 255, 255, 0.16);
  font-weight: 650;
}
.sidebar:hover .nav-item.is-active,
.sidebar:focus-within .nav-item.is-active,
.sidebar:hover .nav-sub.is-active,
.sidebar:focus-within .nav-sub.is-active {
  box-shadow: inset 3px 0 0 #fff;
}
.nav-item.is-disabled,
.nav-sub.is-disabled {
  cursor: default;
}
.nav-item > svg,
.nav-sub svg {
  flex: 0 0 22px;
  width: 22px;
  height: 22px;
}
.nav-item[data-nav-toggle] {
  position: relative;
}
.sidebar:hover .nav-item[data-nav-toggle],
.sidebar:focus-within .nav-item[data-nav-toggle] {
  padding-right: 36px;
}
.nav-caret {
  position: absolute;
  right: 12px;
  top: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  margin: 0;
  opacity: 0;
  overflow: visible;
  pointer-events: none;
  transform: translateY(-50%);
}
.sidebar:hover .nav-caret,
.sidebar:focus-within .nav-caret {
  opacity: 1;
}
.nav-caret svg {
  width: 18px;
  height: 18px;
  flex: none;
  transform: rotate(-90deg);
  transform-origin: 50% 50%;
  transition: transform 0.18s ease;
}
.nav-item.is-expanded .nav-caret svg {
  transform: rotate(0deg);
}
.nav-children {
  display: none;
}
.sidebar:hover .nav-children.is-open,
.sidebar:focus-within .nav-children.is-open {
  display: block;
}
.nav-sub {
  font-size: 13px;
}

.workspace {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 100vh;
  background: var(--bg);
}
.topbar {
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 28px;
  background: rgba(255, 255, 255, 0.92);
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  z-index: 20;
  backdrop-filter: blur(8px);
}
.burger {
  display: flex;
  gap: 8px;
  align-items: center;
  color: var(--navy);
  background: none;
  border: 0;
  cursor: pointer;
  font-family: inherit;
  font-size: 14px;
}
.user-chip {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--ink);
  padding: 4px 8px 4px 4px;
  border-radius: 999px;
}
.user-chip:hover {
  background: var(--soft);
}
.avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--navy);
  color: #fff;
  display: grid;
  place-items: center;
  font-weight: 700;
  font-size: 13px;
}
.user-chip small {
  display: block;
  color: var(--muted);
  font-size: 12px;
}

.page {
  flex: 1;
  padding: 28px 36px 56px;
  max-width: none;
  width: 100%;
}

h1 {
  font-size: 30px;
  font-weight: 700;
  color: var(--navy-deep);
  margin: 0 0 8px;
  letter-spacing: -0.02em;
}
.lead {
  color: var(--muted);
  margin: 0 0 20px;
  max-width: 640px;
  font-size: 16px;
}
.page-head {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  align-items: flex-start;
  margin-bottom: 8px;
}

.who-card {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 12px 14px;
  text-decoration: none;
  color: inherit;
  min-width: 260px;
  box-shadow: var(--shadow);
}
.who-card:hover {
  border-color: var(--navy);
}
.who-card b {
  display: block;
}
.who-card span {
  color: var(--muted);
  font-size: 12.5px;
}
.tint-navy {
  background: #e8eeff;
  color: var(--navy);
}
.tint-amber {
  background: #fff4e5;
  color: #9a6700;
}
.tint-teal {
  background: #e7f6f2;
  color: #0f766e;
}
.tint-slate {
  background: #eef0f8;
  color: var(--navy-deep);
}
.tint-violet {
  background: #f3e8ff;
  color: #6d28d9;
}

.search-hero {
  position: relative;
  margin: 8px 0 22px;
  max-width: 760px;
}
.search-hero input,
.toolbar input {
  width: 100%;
  height: 52px;
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 0 48px 0 18px;
  font-size: 16px;
  font-family: inherit;
  outline: none;
  background: #fff;
  box-shadow: var(--shadow);
}
.search-hero input:focus,
.toolbar input:focus {
  border-color: var(--navy);
  box-shadow: 0 0 0 4px rgba(47, 59, 189, 0.12);
}
.search-ico {
  position: absolute;
  right: 16px;
  top: 16px;
  color: var(--navy);
}

.suggest {
  position: absolute;
  left: 0;
  right: 0;
  top: calc(100% + 6px);
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 12px;
  box-shadow: var(--shadow);
  z-index: 30;
  max-height: 360px;
  overflow: auto;
  display: none;
}
.suggest.is-open {
  display: block;
}
.suggest button {
  display: block;
  width: 100%;
  text-align: left;
  border: 0;
  background: #fff;
  padding: 11px 14px;
  cursor: pointer;
  font-family: inherit;
  font-size: 14px;
}
.suggest button:hover {
  background: var(--soft);
}
.suggest .code {
  color: var(--muted);
  font-size: 12px;
  margin-left: 6px;
}
.suggest .hint {
  color: var(--navy);
  font-size: 12px;
  display: block;
  margin-top: 2px;
}

.section-label {
  margin: 8px 0 12px;
  font-size: 13px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--navy);
  font-weight: 700;
}

.quick-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}
.quick-card {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px;
  background: var(--card);
  text-decoration: none;
  color: inherit;
  min-height: 108px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  box-shadow: var(--shadow);
}
.quick-card:hover,
.svc-card:hover {
  border-color: var(--navy);
}
.quick-card strong {
  color: var(--navy-deep);
  font-size: 15px;
}
.quick-card span {
  color: var(--muted);
  font-size: 13px;
}

.toolbar {
  display: grid;
  grid-template-columns: 1fr 180px auto;
  gap: 12px;
  align-items: end;
  margin: 8px 0 14px;
}
.toolbar label {
  display: block;
  font-size: 12px;
  color: var(--muted);
  margin-bottom: 4px;
}
.toolbar .row {
  position: relative;
}
.toolbar input {
  height: 44px;
  border-radius: 10px;
}
.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0 0 16px;
}
.chip {
  border: 1px solid #d5d8ea;
  background: #fff;
  color: var(--navy);
  border-radius: 999px;
  padding: 7px 12px;
  font-size: 13px;
  cursor: pointer;
  font-family: inherit;
}
.chip.is-on {
  background: var(--navy);
  color: #fff;
  border-color: var(--navy);
}

.meta-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--muted);
  font-size: 13px;
  margin-bottom: 12px;
}
.pager {
  display: flex;
  gap: 4px;
  align-items: center;
}
.pager button,
.btn-ghost,
.btn-primary {
  font-family: inherit;
  cursor: pointer;
}
.pager button {
  min-width: 34px;
  height: 34px;
  border: 1px solid #d5d8ea;
  background: #fff;
  color: var(--navy);
  border-radius: 8px;
}
.pager button.is-on {
  background: var(--navy);
  color: #fff;
  border-color: var(--navy);
}
.pager button:disabled {
  opacity: 0.4;
  cursor: default;
}

.svc-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 14px;
}
.svc-card {
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 16px;
  min-height: 176px;
  display: flex;
  flex-direction: column;
  text-decoration: none;
  color: inherit;
  background: var(--card);
  box-shadow: var(--shadow);
}
.svc-card:hover {
  border-color: var(--navy);
  transform: translateY(-1px);
}
.svc-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}
.svc-icon {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: #e8eeff;
  color: var(--navy);
  display: grid;
  place-items: center;
  margin-bottom: 8px;
}
.svc-grid .svc-card:nth-child(5n + 1) .svc-icon {
  background: #e8eeff;
  color: var(--navy);
}
.svc-grid .svc-card:nth-child(5n + 2) .svc-icon {
  background: #fff4e5;
  color: #9a6700;
}
.svc-grid .svc-card:nth-child(5n + 3) .svc-icon {
  background: #e7f6f2;
  color: #0f766e;
}
.svc-grid .svc-card:nth-child(5n + 4) .svc-icon {
  background: #eef0f8;
  color: var(--navy-deep);
}
.svc-grid .svc-card:nth-child(5n + 5) .svc-icon {
  background: #f3e8ff;
  color: #6d28d9;
}
.star {
  border: 0;
  background: transparent;
  color: #9aa0c3;
  cursor: pointer;
  font-size: 18px;
}
.star.is-on {
  color: var(--navy);
}
.svc-title {
  font-size: 16px;
  font-weight: 650;
  color: var(--navy-deep);
  margin: 0 0 6px;
}
.svc-official {
  font-size: 12.5px;
  color: var(--muted);
  margin: 0;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.badges {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: auto;
  padding-top: 12px;
}
.badge {
  font-size: 11px;
  border-radius: 999px;
  padding: 3px 8px;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  background: #e8eeff;
  color: var(--navy);
  border: 0;
}
.badge.need-id {
  background: #fdecea;
  color: var(--danger);
}
.badge.ecp {
  background: #fff4e5;
  color: #9a6700;
}
.badge.code {
  background: #eef0f8;
  color: var(--muted);
  font-weight: 600;
  text-transform: none;
  letter-spacing: 0;
}

.crumb {
  color: var(--muted);
  font-size: 13px;
  margin-bottom: 14px;
}
.crumb a {
  color: var(--navy);
  text-decoration: none;
}

.official-line {
  color: var(--muted);
  font-size: 14px;
  margin: 0 0 16px;
}
.result-box {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin: 16px 0 20px;
}
.result-item {
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 16px;
  background: var(--card);
  box-shadow: var(--shadow);
  display: grid;
  grid-template-columns: 44px 1fr;
  gap: 12px;
  align-items: start;
}
.result-item:nth-child(1) {
  background: linear-gradient(180deg, #eef1ff 0%, #fff 72%);
}
.result-item:nth-child(2) {
  background: #fffaf2;
  border-color: #edd9b3;
}
.result-item:nth-child(3) {
  background: #f3fbf8;
  border-color: #c7e6dc;
}
.result-item .svc-icon {
  margin: 0;
}
.result-item small {
  display: block;
  color: var(--muted);
  font-size: 12px;
  margin-bottom: 4px;
}
.result-item b {
  font-size: 17px;
  color: var(--navy-deep);
}
.org-line {
  margin: 0 0 22px;
}
.org-line b {
  color: var(--navy-deep);
}

.layout-2 {
  display: grid;
  grid-template-columns: 0.92fr 1.08fr;
  gap: 28px;
  align-items: start;
}
.steps {
  margin: 0;
  padding: 0;
  list-style: none;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 16px;
  box-shadow: var(--shadow);
  overflow: hidden;
}
.steps li {
  display: flex;
  gap: 12px;
  margin: 0;
  padding: 14px 16px;
  border-top: 1px solid var(--line);
  align-items: flex-start;
}
.steps li:first-child {
  border-top: 0;
}
.steps .n {
  width: 28px;
  height: 28px;
  border-radius: 10px;
  background: #e8eeff;
  color: var(--navy);
  display: grid;
  place-items: center;
  font-size: 12px;
  font-weight: 700;
  flex: 0 0 28px;
}

.form-card,
.profile-card {
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 22px;
  background: var(--card);
  box-shadow: var(--shadow);
}
.form-card h2,
.profile-card h2 {
  margin: 0 0 6px;
  font-size: 18px;
  color: var(--navy-deep);
}
.draft-bar {
  font-size: 12.5px;
  color: var(--ok);
  min-height: 18px;
  margin-bottom: 10px;
}
.field {
  margin-bottom: 12px;
}
.field label {
  display: block;
  font-size: 13px;
  margin-bottom: 4px;
  font-weight: 650;
}
.req {
  color: var(--danger);
}
.field input,
.field textarea {
  width: 100%;
  border: 1px solid #d5d8ea;
  border-radius: 10px;
  padding: 10px 12px;
  font-family: inherit;
  font-size: 15px;
  background: #fff;
}
.field input::placeholder,
.field textarea::placeholder {
  color: #9aa0c3;
}
.field textarea {
  min-height: 88px;
  resize: vertical;
}
.field input.is-bad,
.field textarea.is-bad {
  border-color: var(--danger);
  background: #fff6f6;
}
.field input.is-ok {
